import fastapi as FastAPI
import json
import logging
import os
from fastapi.responses import FileResponse
import requests

from pathlib import Path
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware

try:
    from backend.viajes import router as viajes_router
except ModuleNotFoundError:
    from viajes import router as viajes_router

app = FastAPI()
app.include_router(viajes_router)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.get("/robots.txt", include_in_schema=False)
async def robots():
    ruta= Path(__file__).resolve().parent.parent / "robots.txt"
    return FileResponse(ruta,media_type="text/plain")


