def nom_pais_ca(pais):
    return PAISOS_CATALA.get(pais.casefold(), pais.title())


def nom_clima_ca(clima):
    return CLIMES_CATALA.get(clima.casefold(), clima)

def buscar_ciutat(nom):
    nom = nom.strip().casefold()

    for ciutat in cities:
        if ciutat["name"].casefold() == nom:
            return ciutat

    return None


def preparar_ciutat(ciutat):
    return {
        "nombre": ciutat["name"].title(),
        "pais": nom_pais_ca(ciutat["country"]),
        "descripcion": nom_clima_ca(ciutat["climate_type"]),
        "poblacion_millones": round(
            ciutat["population"] / 1_000_000, 2
        ),
        "temperatura_media": ciutat["avg_temp_year"],
        "precipitacion_mm": ciutat["precipitation_mm"],
        "horas_sol": ciutat["sunshine_hours"],
        "humedad": ciutat["humidity_percent"],
        "clima": ciutat["climate_code"]
    }


def generar_conclusion_ia(ciutat_a, ciutat_b, poblacion_a, poblacion_b):
    """Genera una conclusión basada solo en los indicadores comparados."""
    clave = os.getenv("OPENAI_API_KEY")
    if not clave:
        return None, "falta_clave"

    datos = {
        "ciudad_1": ciutat_a,
        "ciudad_2": ciutat_b,
        "poblacion_ciudad_1": poblacion_a,
        "poblacion_ciudad_2": poblacion_b,
    }
    try:
        respuesta = requests.post(
            "https://api.openai.com/v1/responses",
            headers={"Authorization": f"Bearer {clave}"},
            json={
                "model": os.getenv("OPENAI_MODEL", "gpt-5.6-Terra"),
                "instructions": (
                    "Escriu en català una conclusió clara de 2 o 3 frases per a una web de clima. "
                    "Compara les dues ciutats fent servir únicament les dades proporcionades. "
                    "Esmenta diferències concretes de temperatura, pluja, hores de sol o humitat quan n'hi hagi. "
                    "No inventis explicacions, causes ni dades, i no diguis que una ciutat és millor que l'altra. "
                    "Els indicadors anuals són aproximats. Retorna només el text de la conclusió."
                ),
                "input": json.dumps(datos, ensure_ascii=False),
                "max_output_tokens": 180,
                "store": False,
            },
            timeout=25,
        )
        respuesta.raise_for_status()
        contenido = respuesta.json()
        texto = " ".join(
            pieza.get("text", "")
            for elemento in contenido.get("output", [])
            if elemento.get("type") == "message"
            for pieza in elemento.get("content", [])
            if pieza.get("type") == "output_text"
        ).strip()
        if texto:
            return texto, None
        logging.warning("OpenAI no devolvió texto para la conclusión de comparación.")
    except requests.HTTPError as error:
        status = error.response.status_code if error.response is not None else 0
        logging.warning("OpenAI rechazó la conclusión con HTTP %s.", status)
        if status in (401, 403):
            return None, "clave_invalida"
        if status == 429:
            return None, "limite_api"
        if status == 404:
            return None, "modelo_no_disponible"
        if status == 400:
            return None, "peticion_invalida"
        return None, "ia_no_disponible"
    except requests.RequestException as error:
        logging.warning("No se pudo generar la conclusión con OpenAI: %s", error)
        return None, "error_conexion"
    return None, "ia_no_disponible"
@app.get("/comparar")
def comparar(ciudad1: str, ciudad2: str):
    primera = buscar_ciutat(ciudad1)
    segona = buscar_ciutat(ciudad2)

    if primera is None:
        raise HTTPException(
            status_code=404,
            detail=f"No s'ha trobat la ciutat: {ciudad1}"
        )

    if segona is None:
        raise HTTPException(
            status_code=404,
            detail=f"No s'ha trobat la ciutat: {ciudad2}"
        )

    if primera["name"].casefold() == segona["name"].casefold():
        raise HTTPException(
            status_code=400,
            detail="Selecciona dues ciutats diferents."
        )

    ciutat_a = preparar_ciutat(primera)
    ciutat_b = preparar_ciutat(segona)

    comparacion = [
        {
            "caracteristica": "Temperatura mitjana anual",
            "valor1": f'{ciutat_a["temperatura_media"]} °C',
            "valor2": f'{ciutat_b["temperatura_media"]} °C',
            "ganador": ""
        },
        {
            "caracteristica": "Precipitació anual",
            "valor1": f'{ciutat_a["precipitacion_mm"]} mm',
            "valor2": f'{ciutat_b["precipitacion_mm"]} mm',
            "ganador": ""
        },
        {
            "caracteristica": "Hores de sol anuals",
            "valor1": str(ciutat_a["horas_sol"]),
            "valor2": str(ciutat_b["horas_sol"]),
            "ganador": ""
        },
        {
            "caracteristica": "Humitat",
            "valor1": f'{ciutat_a["humedad"]}%',
            "valor2": f'{ciutat_b["humedad"]}%',
            "ganador": ""
        },
        {
            "caracteristica": "Població",
            "valor1": f'{primera["population"]:,}'.replace(",", "."),
            "valor2": f'{segona["population"]:,}'.replace(",", "."),
            "ganador": ""
        }
    ]

    conclusion_ia, conclusion_ia_estado = generar_conclusion_ia(
        ciutat_a, ciutat_b, primera["population"], segona["population"]
    )

    return {
        "ciudades": [ciutat_a, ciutat_b],
        "comparacion": comparacion,
        "conclusion": conclusion_ia,
        "conclusion_ia_estado": conclusion_ia_estado,
    }

@app.get("/ciutats")
def llistar_ciutats():
    return [
        {
            "name": c["name"].title(),
            "country": nom_pais_ca(c["country"]),
            "lat": c["latitude"],
            "lng": c["longitude"],
        }
        for c in cities
    ]
